const items = [...$input.all()].sort((a, b) => Number(b.json.score || b.json.boosted_score || 0) - Number(a.json.score || a.json.boosted_score || 0));
if (items.length === 0) return [];
const selected = items.slice(0, 8);
const timestamp = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', dateStyle: 'medium', timeStyle: 'short' });
const lines = selected.map((item, index) => {
  const p = item.json;
  const score = p.boosted_score ?? p.score ?? 0;
  const reply = p.draft_reply ? `\n   Reply: ${p.draft_reply}` : '';
  return `${index + 1}. ${p.title || 'Untitled signal'} (${p.source || 'unknown'}) - Score: ${score}${reply}\n   ${p.url || ''}`;
}).join('\n\n');
const hiddenCount = Math.max(0, items.length - selected.length);
const hidden = hiddenCount > 0 ? `\n\n...and ${hiddenCount} more medium signal(s) not shown.` : '';
let message = `Signal Digest - ${timestamp}\n\n${lines}${hidden}\n\nTotal medium signals this batch: ${items.length}`;
if (message.length > 3800) message = message.slice(0, 3750).trimEnd() + '\n\n...truncated for Telegram';
return [{ json: { message, dedupe_keys: selected.map(item => item.json.dedupe_key) } }];
